// Nodo "Configuración" del flujo "Secretaria · Recordatorios": lo que se toca a mano está aquí.
// Los demás nodos leen estos valores con $('Configuración').first().json.config
// Los SECRETOS no están aquí: el número de destino se lee del entorno de n8n (WHATSAPP_NUMERO_PERMITIDO, definido en el .env)
// y el token de envío va en una credencial de n8n (Header Auth), no aquí.

// Los identificadores (no son secretos) se leen del .env del servidor, así se ponen UNA vez para todos los flujos.
// Si una variable no está en el .env, vale lo que esté escrito aquí abajo.
const delEntorno = (clave, porDefecto) => {
  try {
    return String($env[clave] ?? '').trim() || porDefecto;
  } catch (e) {
    return porDefecto;
  }
};

// === Valores fáciles de cambiar ===
// Project URL de Supabase (Integrations > Data API), sin /rest/v1 al final. No es un secreto.
const SUPABASE_URL = delEntorno('SUPABASE_URL', 'https://TU-PROYECTO.supabase.co');
// Identificador del número de WhatsApp desde el que se envía (WhatsApp > API Setup > Phone number ID). No es un secreto.
const PHONE_NUMBER_ID = delEntorno('WHATSAPP_PHONE_NUMBER_ID', 'TU-PHONE-NUMBER-ID');
// Versión de la API Graph de Meta (la misma que en el flujo "Secretaria · WhatsApp")
const GRAPH_VERSION = 'v26.0';
// Cuándo avisar, en minutos ANTES de la hora del recordatorio: 1 hora antes, 30 minutos antes y a la hora (0).
// Si cambias esta lista, cambia también AVISOS_RECORDATORIO_MIN en herramientas/flujo/resultado.js (lo que la confirmación promete).
const AVISOS_MIN = [60, 30, 0];
// Horas desde el último mensaje tuyo durante las que Meta admite texto libre. Fuera de ese plazo NO se envía nada y el aviso espera:
// en cuanto vuelvas a escribir, sale (como «atrasado» si la hora ya pasó).
const VENTANA_HORAS = 23;
// Si el aviso «a la hora» sale con más minutos de retraso que estos, se dice que es un recordatorio atrasado
const MARGEN_ATRASADO_MIN = 15;
// Recordatorios que se anuncian como máximo en un solo mensaje
const MAX_POR_MENSAJE = 10;
// ==================================

if (!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(SUPABASE_URL) || SUPABASE_URL.includes('TU-PROYECTO')) {
  throw new Error('Configuración: pon tu Project URL de Supabase en SUPABASE_URL (https://<ref>.supabase.co, sin /rest/v1). Va en el .env del servidor (SUPABASE_URL=…, y después docker compose up -d)');
}
if (!/^\d{8,20}$/.test(PHONE_NUMBER_ID)) {
  throw new Error('Configuración: pon el Phone number ID de WhatsApp en PHONE_NUMBER_ID (solo dígitos). Va en el .env del servidor (WHATSAPP_PHONE_NUMBER_ID=…, y después docker compose up -d)');
}
if (!/^v\d+\.\d+$/.test(GRAPH_VERSION)) {
  throw new Error('Configuración: GRAPH_VERSION debe tener la forma v26.0');
}
if (!Array.isArray(AVISOS_MIN) || AVISOS_MIN.length === 0 || !AVISOS_MIN.every((m) => Number.isInteger(m) && m >= 0 && m <= 1440) || !AVISOS_MIN.includes(0) || new Set(AVISOS_MIN).size !== AVISOS_MIN.length) {
  throw new Error('Configuración: AVISOS_MIN debe ser una lista de minutos distintos, entre 0 y 1440, que incluya el 0 (el aviso «a la hora»)');
}
if (!Number.isFinite(VENTANA_HORAS) || VENTANA_HORAS < 1 || VENTANA_HORAS > 24) {
  throw new Error('Configuración: VENTANA_HORAS debe estar entre 1 y 24');
}
if (!Number.isInteger(MARGEN_ATRASADO_MIN) || MARGEN_ATRASADO_MIN < 1 || MARGEN_ATRASADO_MIN > 720) {
  throw new Error('Configuración: MARGEN_ATRASADO_MIN debe estar entre 1 y 720');
}
if (!Number.isInteger(MAX_POR_MENSAJE) || MAX_POR_MENSAJE < 1 || MAX_POR_MENSAJE > 50) {
  throw new Error('Configuración: MAX_POR_MENSAJE debe estar entre 1 y 50');
}

return [
  {
    json: {
      config: {
        supabase_url: SUPABASE_URL.replace(/\/+$/, ''),
        phone_number_id: PHONE_NUMBER_ID,
        graph_version: GRAPH_VERSION,
        avisos_min: [...AVISOS_MIN].sort((a, b) => b - a),
        ventana_horas: VENTANA_HORAS,
        margen_atrasado_min: MARGEN_ATRASADO_MIN,
        max_por_mensaje: MAX_POR_MENSAJE,
      },
    },
  },
];

// Nodo "Filtrar recordatorios": de las tareas con hora de aviso que devolvió Supabase decide, para cada una, qué aviso toca ahora.
//
// Los avisos son (por defecto) 1 hora antes, 30 minutos antes y a la hora. Cada aviso se manda una sola vez: los ya enviados están en
// recordatorio_avisos. Un aviso «vence» cuando llega su hora; si el recordatorio se creó (o se cambió de hora) DESPUÉS de esa hora,
// no vence nunca (no se avisa tarde de lo que no se prometió). Si varios vencen a la vez (el flujo estuvo parado, o la ventana de 24 h
// estaba cerrada) se anuncia solo el más cercano a la hora y los demás se dan por enviados.
// Cada fila se revalida (uuid, pendiente, título y hora válidos). Si no queda nada devuelve [] y el flujo termina.

const config = $('Configuración').first().json.config;
const ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ms = (s) => (typeof s === 'string' ? Date.parse(s) : NaN);
const ahora = Date.now();

const salida = [];
for (const r of $input.all().map((i) => i.json)) {
  if (!r || typeof r.id !== 'string' || !ID.test(r.id) || r.estado !== 'pendiente') continue;
  if (typeof r.titulo !== 'string' || r.titulo.trim() === '') continue;
  const inicio = ms(r.recordar_en);
  if (Number.isNaN(inicio)) continue;
  const enviados = Array.isArray(r.recordatorio_avisos) ? r.recordatorio_avisos.filter((m) => Number.isInteger(m)) : [];
  const cambio = ms(r.updated_at);

  const vencidos = config.avisos_min.filter((m) => {
    const hora = inicio - m * 60000;
    return !enviados.includes(m) && hora <= ahora && (Number.isNaN(cambio) || hora >= cambio);
  });
  if (vencidos.length === 0) continue;

  const aviso = Math.min(...vencidos); // el más cercano a la hora
  salida.push({
    id: r.id,
    titulo: r.titulo.trim(),
    recordar_en: r.recordar_en,
    aviso,
    atrasado: aviso === 0 && ahora - inicio > config.margen_atrasado_min * 60000,
    avisos_nuevos: [...new Set([...enviados, ...vencidos])].sort((a, b) => b - a),
    hecho: vencidos.includes(0),
  });
}

salida.sort((a, b) => ms(a.recordar_en) - ms(b.recordar_en));
if (salida.length === 0) return [];
return [{ json: { recordatorios: salida.slice(0, config.max_por_mensaje) } }];

// Nodo "Redactar recordatorio": construye UN mensaje de WhatsApp con los recordatorios que toca avisar y el cuerpo exacto de la petición a Meta,
// más lo necesario para marcarlos como avisados DESPUÉS (solo si Meta acepta el envío).
//
// - Solo se envía como texto libre y solo si la ventana de 24 h de Meta sigue abierta (el último mensaje TUYO es de hace menos de
//   VENTANA_HORAS). Si está cerrada devuelve [] y no se envía nada: no se marca nada y el aviso se reintenta cada minuto; en cuanto
//   vuelvas a escribir sale (como «atrasado» si la hora ya pasó).
// - Se redacta con código, nunca con el modelo.
//
//   un recordatorio:   🔔 En 1 hora: *título* (18:30)     🔔 En 30 minutos: *título* (18:30)     🔔 Ahora: *título*
//                      🔔 Recordatorio atrasado (era a las 18:30): *título*
//   varios:            🔔 *Recordatorios*   y una línea «• En 30 minutos: título (18:30)» por cada uno

const config = $('Configuración').first().json.config;
const LIMITE_MENSAJE = 3800;
const ZONA = 'Europe/Madrid';

const limpiar = (s) => String(s ?? '').replace(/[*_~`]/g, '').replace(/\s+/g, ' ').trim();
const fmtHora = new Intl.DateTimeFormat('es-ES', { timeZone: ZONA, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const hora = (iso) => fmtHora.format(new Date(iso));

// Antelación con palabras: 60 -> "1 hora", 120 -> "2 horas", 30 -> "30 minutos"
function antes(minutos) {
  if (minutos > 0 && minutos % 60 === 0) return minutos === 60 ? 'En 1 hora' : `En ${minutos / 60} horas`;
  return `En ${minutos} minutos`;
}

const recordatorios = $('Filtrar recordatorios').first().json.recordatorios;
const ultimo = $('Leer último mensaje')
  .all()
  .map((x) => x.json)
  .filter((r) => r && typeof r.created_at === 'string')
  .map((r) => new Date(r.created_at))
  .filter((d) => !Number.isNaN(d.getTime()))[0];

const ahora = new Date();
const ventanaAbierta = Boolean(ultimo) && ahora.getTime() - ultimo.getTime() < config.ventana_horas * 3600 * 1000;
if (!ventanaAbierta) return [];

const para = String($env.WHATSAPP_NUMERO_PERMITIDO ?? '').replace(/\D/g, '');
if (!para) throw new Error('Redactar recordatorio: falta WHATSAPP_NUMERO_PERMITIDO en el entorno de n8n');

const titulo = (r) => limpiar(r.titulo);
const una = (r) => {
  if (r.atrasado) return `🔔 Recordatorio atrasado (era a las ${hora(r.recordar_en)}): *${titulo(r)}*`;
  if (r.aviso === 0) return `🔔 Ahora: *${titulo(r)}*`;
  return `🔔 ${antes(r.aviso)}: *${titulo(r)}* (${hora(r.recordar_en)})`;
};
const linea = (r) => {
  if (r.atrasado) return `• Atrasado (era a las ${hora(r.recordar_en)}): ${titulo(r)}`;
  if (r.aviso === 0) return `• Ahora: ${titulo(r)}`;
  return `• ${antes(r.aviso)}: ${titulo(r)} (${hora(r.recordar_en)})`;
};

let texto = recordatorios.length === 1 ? una(recordatorios[0]) : `🔔 *Recordatorios*\n${recordatorios.map(linea).join('\n')}`;
if (texto.length > LIMITE_MENSAJE) texto = `${texto.slice(0, LIMITE_MENSAJE - 1).trimEnd()}…`;

return [
  {
    json: {
      cuerpo: { messaging_product: 'whatsapp', recipient_type: 'individual', to: para, type: 'text', text: { preview_url: false, body: texto } },
      texto,
      // Lo que hay que anotar en cada recordatorio DESPUÉS de que Meta acepte el envío
      marcas: recordatorios.map((r) => ({ id: r.id, recordar_en: r.recordar_en, avisos: r.avisos_nuevos, hecho: r.hecho })),
    },
  },
];

// Nodo "Preparar marcas": tras enviar el aviso, una petición por recordatorio para anotar los avisos ya enviados.
// Si era el aviso «a la hora» el recordatorio se da por hecho (ya cumplió su función). Cada petición repite las condiciones de lo que se
// leyó (misma hora de recordatorio, tarea, pendiente): si el usuario cambió la hora o lo completó mientras tanto, no se toca.

const config = $('Configuración').first().json.config;
const marcas = $('Redactar recordatorio').first().json.marcas;

return marcas.map((m) => ({
  json: {
    url: `${config.supabase_url}/rest/v1/items?id=eq.${encodeURIComponent(m.id)}&tipo=eq.tarea&estado=eq.pendiente&recordar_en=eq.${encodeURIComponent(m.recordar_en)}`,
    cuerpo: { recordatorio_avisos: m.avisos, ...(m.hecho ? { estado: 'hecho' } : {}) },
  },
}));

// Nodo "Preparar registro del aviso": tras enviar el aviso, anota en avisos_enviados el id del mensaje que devolvió Meta
// y qué elementos iban en él. Así, si respondes a este aviso («10 minutos más», «muévela a las 12»), el flujo principal sabe de qué
// alarma hablas.
// Si Meta no devolvió un id válido no se anota nada (el aviso ya se mandó; solo se pierde poder responderle).

const config = $('Configuración').first().json.config;
const VALIDO = /^[A-Za-z0-9._=+\/-]{1,300}$/;
const ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const wamid = $input.first()?.json?.messages?.[0]?.id;
if (typeof wamid !== 'string' || !VALIDO.test(wamid)) return [];

const redactado = $('Redactar recordatorio').first().json;
const ids = [...new Set((redactado.marcas ?? []).map((x) => (typeof x === 'string' ? x : x?.id)).filter((i) => typeof i === 'string' && ID.test(i)))];
if (ids.length === 0) return [];

return [
  {
    json: {
      url: `${config.supabase_url}/rest/v1/avisos_enviados?on_conflict=wa_message_id,item_id`,
      cuerpo: ids.map((id) => ({ wa_message_id: wamid, item_id: id, tipo: 'alarma' })),
    },
  },
];
